#include <bits/stdc++.h>
#include <sys/resource.h>
using namespace std;
struct Letter{int o,a,b;bool operator<(const Letter&x)const{return tie(o,a,b)<tie(x.o,x.a,x.b);}bool operator==(const Letter&x)const{return tie(o,a,b)==tie(x.o,x.a,x.b);}};
using Word=vector<Letter>;using P=map<Word,int>;struct Edge{int a,b;};vector<Edge> es;int table[3][16][16];map<unsigned,P> groups;
P bracket(P p,P q){P r;for(auto [a,x]:p)for(auto [b,y]:q){Word ab=a,ba=b;ab.insert(ab.end(),b.begin(),b.end());ba.insert(ba.end(),a.begin(),a.end());r[ab]+=x*y;r[ba]-=x*y;}return r;}
P atom(int op,int e){P p;p[Word{Letter{op,es[e].a,es[e].b}}]=1;return p;}
unsigned sm(int e){return (1u<<es[e].a)|(1u<<es[e].b);}int tr(int i,int t){return ((i/4+t/4)%8)*4+(i%4+t%4)%4;}
unsigned transmask(unsigned s,int t){unsigned z=0;for(int i=0;i<32;i++)if(s>>i&1)z|=1u<<tr(i,t);return z;}
void collect(P p){unsigned s=0;for(auto[w,c]:p)if(c)for(auto a:w)s|=(1u<<a.a)|(1u<<a.b);if(!s)return;unsigned best=s;int bt=0;for(int t=1;t<32;t++){auto z=transmask(s,t);if(z<best){best=z;bt=t;}}for(auto[ww,c]:p)if(c){Word w=ww;for(auto& l:w){l.a=tr(l.a,bt);l.b=tr(l.b,bt);if(l.a>l.b)swap(l.a,l.b);}groups[best][w]+=c;}}
void apply(const Word&w,int i,int state,long long c,vector<long long>&out){if(i<0){out[state]+=c;return;}auto l=w[i];int a=state>>(2*l.a)&3,b=state>>(2*l.b)&3,base=state&~((3<<(2*l.a))|(3<<(2*l.b)));for(int dst=0;dst<16;dst++)if(table[l.o][a+4*b][dst])apply(w,i-1,base|((dst%4)<<(2*l.a))|((dst/4)<<(2*l.b)),c*table[l.o][a+4*b][dst],out);}
int main(int argc,char**argv){ifstream tab(string(argv[1])+"/edge_table.txt");for(auto&op:table)for(auto&src:op)for(int&v:src)tab>>v;set<pair<int,int>> ss;for(int i=0;i<32;i++)for(int j:{tr(i,1),tr(i,4)})ss.insert(minmax(i,j));for(auto [a,b]:ss)es.push_back({a,b});assert(es.size()==64);for(int e=0;e<64;e++){set<unsigned> orbit;for(int t=0;t<32;t++)orbit.insert(transmask(sm(e),t));assert(orbit.size()==32);}vector<int> anchors;for(int e=0;e<64;e++)if(es[e].a==0&&(es[e].b==1||es[e].b==4))anchors.push_back(e);
for(string fam:{"N","F","L"}){groups.clear();int tuples=0;if(fam!="F")for(int k:anchors)for(int j=0;j<64;j++)if(sm(k)&sm(j))for(int i=0;i<64;i++)if(sm(i)&(sm(j)|sm(k))){P p=bracket(atom(0,i),bracket(atom(fam=="N"?2:0,j),atom(1,k)));if(fam=="N"){collect(p);tuples++;}else for(int l=0;l<64;l++)if(sm(l)&(sm(i)|sm(j)|sm(k))){collect(bracket(p,atom(1,l)));tuples++;}}
if(fam=="F")for(int i:anchors)for(int j=0;j<64;j++)if(sm(i)&sm(j))for(int k=0;k<64;k++)for(int l=0;l<64;l++)if((sm(k)&sm(l))&&((sm(i)|sm(j))&(sm(k)|sm(l)))){collect(bracket(bracket(atom(0,i),atom(2,j)),bracket(atom(2,k),atom(1,l))));tuples++;}
ifstream bin(string(argv[2])+"/run/rules_"+fam+".bin",ios::binary);long records=0,zeros=0,neg=0;map<int,int> stabilizers;for(auto[s,p]:groups){vector<int> sites;for(int i=0;i<32;i++)if(s>>i&1)sites.push_back(i);int dim=1<<(2*sites.size());assert(dim<=1024);int stab=0;for(int t=0;t<32;t++)stab+=transmask(s,t)==s;stabilizers[stab]++;vector<pair<Word,int>> local;for(auto[ww,c]:p)if(c){Word w=ww;for(auto&l:w){l.a=find(sites.begin(),sites.end(),l.a)-sites.begin();l.b=find(sites.begin(),sites.end(),l.b)-sites.begin();}local.push_back({w,c});}for(int src=0;src<dim;src++){vector<long long> out(dim);for(auto[w,c]:local)apply(w,w.size()-1,src,c,out);for(int dst=0;dst<dim;dst++)if(out[dst]){unsigned rs;uint16_t a,b;int32_t c;assert(bin.read((char*)&rs,4));bin.read((char*)&a,2);bin.read((char*)&b,2);bin.read((char*)&c,4);assert(rs==s&&a==src&&b==dst&&c==out[dst]);records++;neg+=c<0;}else zeros++;}}
assert(bin.peek()==EOF);cout<<fam<<" tuples="<<tuples<<" supports="<<groups.size()<<" records="<<records<<" zeros="<<zeros<<" negative="<<neg<<" stabilizers=";for(auto[k,v]:stabilizers)cout<<k<<":"<<v<<",";cout<<" PASS\n";}
rusage r{};getrusage(RUSAGE_SELF,&r);cout<<"CPU="<<r.ru_utime.tv_sec+r.ru_utime.tv_usec/1e6+r.ru_stime.tv_sec+r.ru_stime.tv_usec/1e6<<" RSS_KiB="<<r.ru_maxrss<<endl;
}
